scenario:
주니어 개발자가 카운터 컴포넌트를 작성했는데 버튼을 클릭해도 값이 1만 증가합니다.

function Counter() {
  const [count, setCount] = useState(0);
  const handleClick = () => {
    setCount(count + 1);
    setCount(count + 1);
    setCount(count + 1);
  };
  return <button onClick={handleClick}>{count}</button>;
}

버튼 클릭 이벤트 핸들러에서 this가 예상과 다른 객체를 가리키는 버그를 디버깅 중입니다.

class Button {
  constructor() { this.text = 'Click'; }
  handle() { console.log(this.text); }
}
const btn = new Button();
element.addEventListener('click', btn.handle);

